import React, { useState, useEffect } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

// Benchmarks text based on Savings Category
const benchmarks = {
  mmtgDealexecution: "Infra benchmark guidelines: Infra automation usually targets server provisioning, cloud infra, etc.",
  mmtgDealexecution: "License benchmark guidelines: License cost optimization benchmarks go here.",
  TestCaseCreation: "Productivity benchmark guidelines: Productivity automation benchmarks, e.g. CI/CD pipelines, dashboards.",
  TestCaseExecution: "Productivity benchmark guidelines: Productivity automation benchmarks, e.g. CI/CD pipelines, dashboards."
};

const ProjectLeadROIEntry = () => {
  const { intakeNumber } = useParams();
  const [rows, setRows] = useState([
    {
      Release: "",
      ROIMonth: "",
      ProjectName: "",
      AutomationLead: "",
      SavingsCategory: "",
      AutomationFmk: "",
      TotalTCsCount: "",
      ManualTCsPD: "",
      AutomatedTCCreatedPD: "",
      NumberofCycles: "",
      TotalManualPD: 0,
      TotalManualCost: 0,
      TotalAutomatedPD: 0,
      TotalAutomationCost: 0,
      Savings: 0,
    },
  ]);
  const [projectDetails, setProjectDetails] = useState(null);
  const [popupText, setPopupText] = useState("");

  // Fetch ProjectName and AutomationLead from DB
  useEffect(() => {
    if (intakeNumber) {
      axios
        .get(`http://localhost:5000/api/projects/${intakeNumber}`)
        .then((res) => {
          setProjectDetails(res.data);
          setRows((prev) =>
            prev.map((row) => ({
              ...row,
              ProjectName: res.data.ProjectName,
              AutomationLead: res.data.AutomationLead,
            }))
          );
        })
        .catch((err) => console.error("Error fetching project details", err));
    }
  }, [intakeNumber]);

  // Formula calculations
  const calculateFormulas = (row) => {
    const manualPD =
      parseInt(row.TotalTCsCount || 0) * parseInt(row.ManualTCsPD || 0);
    const manualCost = manualPD * 100; // Example multiplier
    const automatedPD =
      parseInt(row.AutomatedTCCreatedPD || 0) *
      parseInt(row.NumberofCycles || 0);
    const automationCost = automatedPD * 50; // Example multiplier
    const savings = manualCost - automationCost;

    return {
      TotalManualPD: manualPD,
      TotalManualCost: manualCost,
      TotalAutomatedPD: automatedPD,
      TotalAutomationCost: automationCost,
      Savings: savings,
    };
  };

  // Handle input change
  const handleChange = (index, field, value) => {
    const newRows = [...rows];
    newRows[index][field] = value;

    // Recalculate formulas
    const formulas = calculateFormulas(newRows[index]);
    newRows[index] = { ...newRows[index], ...formulas };

    setRows(newRows);
  };

  // Fetch TC Count from ALM
  const fetchFromALM = async (index) => {
    try {
      const res = await axios.get("http://localhost:5000/api/fetch_tc_count");
      const count = res.data.count || 0;
      const newRows = [...rows];
      newRows[index].TotalTCsCount = count;
      setRows(newRows);
    } catch (err) {
      alert("Failed to fetch from ALM");
    }
  };

  // Show benchmark popup
  const showBenchmark = (category) => {
     const msg =
       benchmarks[category] || "No benchmark available for this category";
     window.alert(msg);
   };

  // Add new row
  const addRow = () => {
    setRows([
      ...rows,
      {
        Release: "",
        ROIMonth: "",
        ProjectName: projectDetails?.ProjectName || "",
        AutomationLead: projectDetails?.AutomationLead || "",
        SavingsCategory: "",
        AutomationFmk: "",
        TotalTCsCount: "",
        ManualTCsPD: "",
        AutomatedTCCreatedPD: "",
        NumberofCycles: "",
        TotalManualPD: 0,
        TotalManualCost: 0,
        TotalAutomatedPD: 0,
        TotalAutomationCost: 0,
        Savings: 0,
      },
    ]);
  };

  // Save rows to backend
  const saveRows = () => {
    const payload = {
      entries: rows.map((row) => ({
        intake_number: intakeNumber,
        ...row,
      })),
    };

    axios
      .post("http://localhost:5000/api/projectroientry", payload)
      .then(() => alert("Entries saved successfully"))
      .catch(() => alert("Error saving entries"));
  };

  return (
    <div className="p-4">
      <h2 className="text-2xl font-bold mb-4">Project ROI Entry</h2>

      {rows.map((row, index) => (
        <div
          key={index}
          className="mb-6 border-2 border-gray-400 p-4 rounded-lg shadow bg-white flex gap-6"
        >
          {/* Section 1: Project Details (only in first row) */}
          {index === 0 && (
            <div className="flex-1 border-r pr-4">
              <h3 className="text-lg font-semibold mb-2">Project Details</h3>
              <div className="space-y-3">
                <div>
                  <input
                    type="text"
                    placeholder="Release"
                    value={row.Release}
                    onChange={(e) =>
                      handleChange(index, "Release", e.target.value)
                    }
                  />
                  <label className="block text-sm text-gray-600">Release</label>
                </div>
                <div>
                  <input
                    type="text"
                    placeholder="ROI Month"
                    value={row.ROIMonth}
                    onChange={(e) =>
                      handleChange(index, "ROIMonth", e.target.value)
                    }
                  />
                  <label className="block text-sm text-gray-600">ROI Month</label>
                </div>
                <div>
                  <input type="text" value={row.ProjectName} disabled />
                  <label className="block text-sm text-gray-600">
                    Project Name
                  </label>
                </div>
                <div>
                  <input type="text" value={row.AutomationLead} disabled />
                  <label className="block text-sm text-gray-600">
                    Automation Lead
                  </label>
                </div>
              </div>
            </div>
          )}

          {/* Section 2: ROI Entry */}
          <div className="flex-1 border-r pr-4">
            <h3 className="text-lg font-semibold mb-2">ROI Entry</h3>
            <div className="space-y-3">
              <div>
                <select
                  value={row.SavingsCategory}
                  onChange={(e) =>
                    handleChange(index, "SavingsCategory", e.target.value)
                  }
                >
                  <option value="">Select Savings Category</option>
                  <option value="mmtgDealexecution">mmtg Deal execution</option>
                  <option value="savvyDealexecution">savvy Deal execution</option>
                  <option value="TestCaseCreation">Test Case Creation</option>
				  <option value="TestCaseExecution">Test Case Execution</option>
                </select>
                <label className="block text-sm text-gray-600">
                  Savings Category
                </label>
              </div>

              {/* Total TCs Count with Fetch button + Dynamic Label */}
              <div>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    value={row.TotalTCsCount}
                    onChange={(e) =>
                      handleChange(index, "TotalTCsCount", e.target.value)
                    }
                  />
                  <button
                    onClick={() => fetchFromALM(index)}
                    className="px-2 py-1 bg-blue-500 text-white rounded"
                  >
                    Fetch from ALM
                  </button>
                </div>
                <label className="block text-sm text-gray-600">
                  {row.SavingsCategory
                    ? `Total ${row.SavingsCategory} Count`
                    : "Total TCs Count"}
                </label>
              </div>

              <div>
                <input
                  type="number"
                  placeholder="Manual TCs PD"
                  value={row.ManualTCsPD}
                  onChange={(e) =>
                    handleChange(index, "ManualTCsPD", e.target.value)
                  }
                />
                <label className="block text-sm text-gray-600">Manual TCs PD</label>
              </div>

              {/* Automated TC Created PD + Benchmark button */}
              <div>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    placeholder="Automated TC Created PD"
                    value={row.AutomatedTCCreatedPD}
                    onChange={(e) =>
                      handleChange(index, "AutomatedTCCreatedPD", e.target.value)
                    }
                  />
                  <button
                    onClick={() => showBenchmark(row.SavingsCategory)}
                    className="px-2 py-1 bg-purple-500 text-white rounded"
                  >
                    Refer Benchmark
                  </button>
                </div>
                <label className="block text-sm text-gray-600">
                  Automated TC Created PD
                </label>
              </div>

              <div>
                <input
                  type="number"
                  placeholder="Number of Cycles"
                  value={row.NumberofCycles}
                  onChange={(e) =>
                    handleChange(index, "NumberofCycles", e.target.value)
                  }
                />
                <label className="block text-sm text-gray-600">
                  Number of Cycles
                </label>
              </div>
            </div>
          </div>

          {/* Section 3: ROI Calculations */}
          <div className="flex-1">
            <h3 className="text-lg font-semibold mb-2">ROI Calculations</h3>
            <div className="grid grid-cols-1 gap-3">
              <div>
                <input type="number" value={row.TotalManualPD} disabled />
                <label className="block text-sm text-gray-600">
                  Total Manual PD
                </label>
              </div>
              <div>
                <input type="number" value={row.TotalManualCost} disabled />
                <label className="block text-sm text-gray-600">
                  Total Manual Cost
                </label>
              </div>
              <div>
                <input type="number" value={row.TotalAutomatedPD} disabled />
                <label className="block text-sm text-gray-600">
                  Total Automated PD
                </label>
              </div>
              <div>
                <input type="number" value={row.TotalAutomationCost} disabled />
                <label className="block text-sm text-gray-600">
                  Total Automation Cost
                </label>
              </div>
              <div>
                <input type="number" value={row.Savings} disabled />
                <label className="block text-sm text-gray-600">Savings</label>
              </div>
            </div>
          </div>
        </div>
      ))}

      {/* Action buttons */}
      <button
        onClick={addRow}
        className="px-4 py-2 bg-blue-500 text-white rounded mr-2"
      >
        Add Row
      </button>
      <button
        onClick={saveRows}
        className="px-4 py-2 bg-green-500 text-white rounded"
      >
        Save
      </button>

      {/* Popup for benchmarks */}
      {popupText && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-40">
          <div className="bg-white p-6 rounded shadow-lg w-1/3">
            <p className="mb-4">{popupText}</p>
            <button
              onClick={() => setPopupText("")}
              className="px-4 py-2 bg-red-500 text-white rounded"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProjectLeadROIEntry;
